// The two buttons are the whole mechanism: each one is a link back into THIS execution.
//
// $execution.resumeUrl already carries the execution's resume token as ?signature=... — n8n generates that
// token when the execution's run data is created, so it exists here, before the Wait node has run. The
// waiting webhook answers 401 without it, which is why `approved` is appended with **&** and never with ?.
// (A wrong separator would drop the token and every button would 401. Verified against n8n 2.46.7:
// core/.../get-additional-keys.ts appends `signature`, cli/.../waiting-webhooks.ts rejects a call without it.)
const req = $input.first().json;
const body = req.body ?? {};

const ref = String(body.ref ?? '').trim();
const requester = String(body.requester ?? '').trim();
const reason = String(body.reason ?? '').trim();
const amountVnd = Number(body.amountVnd);

// Refuse rather than ask for a decision nobody can act on: a card without a reference is unmatchable, and
// an approval for an unknown amount is not an approval.
if (!ref || !requester || !Number.isFinite(amountVnd)) {
  throw new Error('need ref, requester and a numeric amountVnd in the body');
}

const approveUrl = `${$execution.resumeUrl}&approved=true`;
const rejectUrl = `${$execution.resumeUrl}&approved=false`;

// Thousands separators without Intl on purpose: the n8n image is Alpine-based and a small-ICU build would
// silently format 'vi-VN' as en-US instead of failing, so the grouping is done by hand.
const money = String(Math.round(amountVnd)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');

return [
  {
    json: {
      ref,
      requester,
      reason,
      amountVnd,
      approveUrl,
      rejectUrl,
      // Google Chat's cardsV2 payload. An incoming webhook accepts this as-is — no OAuth, no Chat app:
      // the space's URL is the credential, which is why this template needs no n8n credential at all.
      card: {
        cardsV2: [
          {
            cardId: `approval-${ref}`,
            card: {
              header: {
                title: 'Duyệt chi · Expense approval',
                subtitle: `${ref} · ${money} ₫`,
              },
              sections: [
                {
                  widgets: [
                    { decoratedText: { topLabel: 'Người đề nghị · Requester', text: requester } },
                    { decoratedText: { topLabel: 'Lý do · Reason', text: reason || '—' } },
                    {
                      buttonList: {
                        buttons: [
                          { text: 'Approve', onClick: { openLink: { url: approveUrl } } },
                          { text: 'Reject', onClick: { openLink: { url: rejectUrl } } },
                        ],
                      },
                    },
                  ],
                },
              ],
            },
          },
        ],
      },
    },
  },
];

// ----------------------------------------------------------------------------------------------------
// REPLACE THIS NODE with whatever the approval unlocks: pay the invoice, release the discount, post the
// order. Everything before it is the approval; this is the part that costs money.
// ----------------------------------------------------------------------------------------------------
//
// Two things to keep in mind when you do:
//  1. A button link can be clicked twice, and a browser can prefetch it. Make the action idempotent —
//     docs/operations/idempotency.md is the pattern, and templates/idempotent-webhook/ is a working gate.
//  2. .first() rather than .item on purpose: paired-item tracking does not survive the wait reliably, and
//     one approval is one item, so there is nothing to pair.
const d = $('Build the approval card').first().json;

return [
  {
    json: {
      outcome: 'approved',
      ref: d.ref,
      requester: d.requester,
      amountVnd: d.amountVnd,
      respondedAt: new Date().toISOString(),
    },
  },
];

// The rejection path exists so a "no" is recorded rather than dropped: without it, a rejected request and
// a request nobody ever answered look identical afterwards.
const d = $('Build the approval card').first().json;

return [
  {
    json: {
      outcome: 'rejected',
      ref: d.ref,
      requester: d.requester,
      amountVnd: d.amountVnd,
      respondedAt: new Date().toISOString(),
    },
  },
];
